import './config.js';
import { createSessionStore } from './session.mjs';
'use strict';
(() => {
const $ = (s, root = document) => root.querySelector(s);
const app = $('#app'), dialog = $('#review-dialog');
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {
 grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
 users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M15 3.13a4 4 0 0 1 0 7.75"/><circle cx="9" cy="7" r="4"/>',
 shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="m8.5 12 2.5 2.5 4.5-5"/>',
 log:'<path d="M8 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V5a2 2 0 0 0-2-2h-3"/><rect x="8" y="1" width="8" height="4" rx="1"/><path d="M7 10h10M7 14h10M7 18h6"/>',
 chat:'<path d="M21 11.5a8.4 8.4 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.4 8.4 0 0 1-3.8-.9L3 21l1.9-5.7a8.4 8.4 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.4 8.4 0 0 1 3.8-.9h.5a8.5 8.5 0 0 1 8 8v.5Z"/>',
 settings:'<path d="M4 5h16M4 12h16M4 19h16"/><circle cx="8" cy="5" r="2"/><circle cx="16" cy="12" r="2"/><circle cx="10" cy="19" r="2"/>',
 arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',
 exit:'<path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4m7 14 5-5-5-5M9 12h12"/>',
 lock:'<rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4m-4 4v3"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
 rank:'<path d="m5 11 7-7 7 7M5 19l7-7 7 7"/>',
 external:'<path d="M14 3h7v7m0-7L10 14M10 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-5"/>',
 refresh:'<path d="M20 7a9 9 0 0 0-15-2L2 8m0-6v6h6m-4 9a9 9 0 0 0 15 2l3-3m0 6v-6h-6"/>',
 copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V4a2 2 0 0 0-2-2H4a2 2 0 0 0-2 2v10a2 2 0 0 0 2 2h4"/>',
 download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',
 menu:'<path d="M4 6h16M4 12h16M4 18h16"/>'
};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name] || paths.grid}</svg>`;
const brand = () => '<div class="brand"><span class="brand-mark"><img src="serverh-logo.png" alt="Rainbow H"></span><span>ServerH<span class="slash">.</span></span></div>';
const labels = {'assign-role':'Assign role','remove-role':'Remove role','kick':'Kick from group','group-ban':'Ban from group','group-unban':'Unban from group','experience-ban':'Ban from experience','experience-unban':'Unban from experience'};
const names = { overview:'Overview', members:'People', moderation:'Moderation', audit:'Audit log', chat:'Staff chat', system:'Connection' };
const apiBase = String(window.SERVERH_CONFIG?.apiBase || location.origin).replace(/\/$/, '');
const navMedia = window.matchMedia('(max-width:820px)');
let tabStorage; try { tabStorage = window.sessionStorage; } catch {}
const sessions = createSessionStore(tabStorage, apiBase);
let sessionToken = null, actor = null, current = 'overview', me = null, audit = [], selected = null, review = null, toastTimer, viewEpoch = 0, chatTimer;
const frameNames={rank:'Rank frame',crimson:'Crimson',steel:'Steel',rainbow:'Spectrum',none:'No frame'};
function avatar(v,extra=''){const frame=v.frame==='rank'||!v.frame?v.rankFrame:v.frame;const known=['gold','violet','crimson','steel','rainbow','none'].includes(frame)?frame:'none';return `<span class="avatar framed frame-${known} ${extra}"><span>${esc((v.name||'SH').slice(0,2).toUpperCase())}</span>${v.avatarUrl?`<img src="${esc(v.avatarUrl)}" alt="${esc(v.name)}’s Roblox avatar" loading="lazy" referrerpolicy="no-referrer">`:''}</span>`;}
function badges(v){return `<span class="rank-badges">${(v.badges||[]).map(b=>`<span class="rank-tag tone-${['gold','violet','crimson','steel'].includes(b.tone)?b.tone:'steel'}">${esc(b.label)}</span>`).join('')||`<span class="directory-role">${esc(v.role||'')}</span>`}</span>`;}
document.addEventListener('error',event=>{if(event.target.matches?.('.avatar img,.workspace-symbol img'))event.target.remove();},true);
function toast(message) { $('#toast').textContent=message; $('#toast').classList.add('show'); clearTimeout(toastTimer); toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5500); }
function errorBox(root, message) { let el=$('.inline-error',root); if(!el){el=document.createElement('div');el.className='inline-error';el.setAttribute('role','alert');root.prepend(el);}el.textContent=message; }
function busy(button, active, label) { if (!button) return; if(active){button.dataset.previous=button.innerHTML;button.disabled=true;button.innerHTML='<span class="spinner"></span>'+esc(label||'Working');}else{button.innerHTML=button.dataset.previous;button.disabled=false;} }
async function api(path, {method='GET', data, anonymous=false}={}) {
 const headers={'Content-Type':'application/json'};
 if(sessionToken&&!anonymous) headers.Authorization=`Bearer ${sessionToken}`;
 let response;
 try { response=await fetch(`${apiBase}/api${path}`,{method,headers,credentials:'omit',cache:'no-store',signal:AbortSignal.timeout(60000),...(data?{body:JSON.stringify(data)}:{})}); }
 catch { throw new Error('Cannot reach the private backend. Check its address and connection, then try again.'); }
 let body; try { body=await response.json(); } catch { throw new Error('The backend is not connected. Set its HTTPS address in config.js.'); }
 if(!response.ok){
  if(!anonymous&&sessionToken&&(response.status===401||(response.status===403&&path==='/me'))){resetSession();login();}
  throw new Error(body.error||'The request could not be completed.');
 }
 return body;
}
function resetSession(){clearTimeout(chatTimer);sessions.clear();sessionToken=null;actor=null;me=null;audit=[];selected=null;review=null;dialog.close();}
function login(challenge=null) {
 viewEpoch++;
 app.innerHTML=`<main class="login page-enter"><div class="login-left">${brand()}<section class="login-form" aria-label="Connect Roblox account">${challenge?verificationHTML(challenge):`<div class="eyebrow">Staff access / ServerH</div><h1>Keep things<br>under control.</h1><p class="muted">Your group. Your people. One place to manage it.<br>Connect your Roblox account to get started.</p><form id="login-form"><div class="field"><label for="username">Roblox username</label><input id="username" name="username" placeholder="Your username, not display name" required minlength="3" maxlength="20" pattern="[A-Za-z0-9_]{3,20}" autocomplete="username" spellcheck="false"><p class="hint">We’ll verify ownership through your Roblox bio.</p></div><button class="button primary wide" type="submit">Continue with Roblox ${icon('arrow')}</button></form><div class="divider"></div><div class="row muted">${icon('lock')}<span class="hint">Lead Operator and higher. Account verification required.</span></div>`}</section><footer class="login-footer"><span>SERVERH CONTROL / STAFF OPERATIONS</span><span>Independent community tool</span></footer></div><aside class="login-right" aria-label="ServerH operations"><div class="row between"><span class="eyebrow">Operations, in order.</span><span class="mono">SH / 01</span></div><div class="specimen" aria-hidden="true"><div class="orbit"></div><div class="orbit inner"></div><img class="monogram" src="serverh-logo.png" alt=""><span class="coordinate c1">988023438 / COMMUNITY</span><span class="coordinate c2">7933292768 / EXPERIENCE</span></div><div><div class="right-copy"><span class="eyebrow">A quieter kind of control</span><h2>Built for the people<br>behind the server.</h2><p>Handle ranks, manage members, and make the right call.<br>Every action has a reason. Every change leaves a record.</p></div><div class="right-bottom"><span class="row"><span class="dot"></span> Restricted staff environment</span><a href="https://www.roblox.com/communities/988023438/ServerH#!/about" target="_blank" rel="noopener noreferrer">Visit community ${icon('external')}</a></div></div></aside></main>`;
 if(challenge){bindVerification(challenge);return;}
 $('#login-form').addEventListener('submit',async e=>{
  e.preventDefault();const form=e.currentTarget,btn=$('button',form);busy(btn,true,'Finding account');
  try{const c=await api('/auth/challenge',{method:'POST',data:{username:$('#username').value.trim()},anonymous:true});login(c);}catch(err){errorBox(form,err.message);}finally{if(btn.isConnected)busy(btn,false);}
 });
}
function verificationHTML(c){return `<div class="steps" aria-label="Verification step 2 of 3"><span class="step on"></span><span class="step on"></span><span class="step"></span></div><div class="eyebrow">02 / Verify ownership</div><h1>A quick bio check.</h1><p class="muted">Add this exact phrase anywhere in your Roblox bio, save your changes, then verify below.</p><div class="verification-name row">${avatar(c.user)}<span><b>@${esc(c.user.name)}</b><br><span class="muted mono">${esc(c.user.id)}</span></span></div><div class="phrase" id="verification-phrase">${esc(c.phrase)}</div><div class="row between"><button class="text-button row" id="copy-phrase" type="button">${icon('copy')} Copy phrase</button><span class="mono muted">Expires in 10 minutes</span></div><a class="button ghost wide" href="https://www.roblox.com/users/${esc(c.user.id)}/profile#!/about" target="_blank" rel="noopener noreferrer">Open my Roblox bio ${icon('external')}</a><p class="hint">Edit your About / description. You can remove the phrase after connecting.</p><div class="divider"></div><form id="verify-form"><button class="button primary wide" type="submit">I saved it. Verify my account ${icon('arrow')}</button></form><div class="row between"><button class="text-button" id="new-phrase" type="button">Get four new words</button><button class="text-button" id="back-login" type="button">Use a different account</button></div>`;}
function bindVerification(c){
 $('#back-login').addEventListener('click',()=>login());
 $('#new-phrase').addEventListener('click',async e=>{const btn=e.currentTarget;busy(btn,true,'Getting words');try{const fresh=await api('/auth/challenge',{method:'POST',data:{username:c.user.name},anonymous:true});login(fresh);}catch(err){errorBox($('#verify-form'),err.message);}finally{if(btn.isConnected)busy(btn,false);}});
 $('#copy-phrase').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(c.phrase);toast('Verification phrase copied.');}catch{toast('Select the phrase and copy it manually.');}});
 $('#verify-form').addEventListener('submit',async e=>{
  e.preventDefault();const btn=$('button',e.currentTarget);busy(btn,true,'Verifying bio and role');
  try{const result=await api('/auth/verify',{method:'POST',data:{challengeToken:c.challengeToken},anonymous:true});sessionToken=result.token;actor=result.user;sessions.save(sessionToken,actor.expires);await loadPanel();}
  catch(err){if(btn.isConnected)errorBox(e.target,err.message);}finally{if(btn.isConnected)busy(btn,false);}
 });
}
async function loadPanel(){
 const result=await api('/me');me=result;actor=result.user;sessions.save(sessionToken,actor.expires);
 audit=(await api('/audit')).entries;shell();navigate('overview');
}
function shell(){
 if(!sessionToken||!actor)return login();
 app.innerHTML=`<div class="shell page-enter"><aside class="sidebar" aria-label="Main navigation">${brand()}<button id="close-menu" class="icon-button sidebar-close" aria-label="Close navigation">${icon("exit")}</button><div class="eyebrow workspace-label">Workspace</div><a class="workspace" href="https://www.roblox.com/communities/988023438/ServerH#!/about" target="_blank" rel="noopener noreferrer"><span class="workspace-symbol">SH${me.group?.iconUrl?`<img src="${esc(me.group.iconUrl)}" alt="ServerH group icon" referrerpolicy="no-referrer">`:""}</span><span><b>ServerH</b><small>ROBLOX COMMUNITY</small></span>${icon('external')}</a><div class="eyebrow nav-label">Control panel</div><nav class="nav">${Object.entries(names).map(([key,name],i)=>`<button data-nav="${key}" type="button">${icon(['grid','users','shield','log','chat','settings'][i])}<span>${name}</span><span class="num">0${i+1}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="side-note">${icon('lock')}<br>Access is checked against your<br>Roblox role on every request.</div><div class="operator">${avatar(actor)}<span class="operator-info"><b>${esc(actor.name)}</b>${badges(actor)}</span><button id="logout" class="icon-button" aria-label="Sign out" title="Sign out">${icon('exit')}</button></div></div></aside><button id="menu-overlay" class="menu-overlay" aria-label="Close navigation" tabindex="-1"></button><main class="main"><header class="topbar"><div class="row"><button id="menu-toggle" class="icon-button mobile-toggle" aria-label="Toggle navigation" aria-expanded="false">${icon('menu')}</button><div class="breadcrumb"><span>Workspace</span><span>/</span><span id="crumb">Overview</span></div></div><div class="topbar-right"><span class="mono" id="session-clock">SESSION / 60:00</span><span class="pill green"><span class="dot"></span>Account verified</span></div></header><div class="content" id="content"></div></main></div>`;
 $('.nav').addEventListener('click',e=>{const btn=e.target.closest('[data-nav]');if(btn)navigate(btn.dataset.nav);});
 $('#menu-toggle').addEventListener('click',()=>{ $('.shell').classList.toggle('menu-open'); syncMenu(); });
 $('#close-menu').addEventListener('click',closeMenu);$('#menu-overlay').addEventListener('click',closeMenu);syncMenu();
 $('#logout').addEventListener('click',logout);
}
function syncMenu(){const shell=$('.shell');if(!shell)return;const open=shell.classList.contains('menu-open');$('.sidebar').inert=navMedia.matches&&!open;$('#menu-toggle').setAttribute('aria-expanded',String(open));}
function closeMenu(){const shell=$('.shell');if(!shell)return;shell.classList.remove('menu-open');syncMenu();if(navMedia.matches)$('#menu-toggle').focus();}
navMedia.addEventListener('change',syncMenu);
async function logout(){if(sessionToken){try{await api('/auth/logout',{method:'POST',data:{}});}catch{ /* The local session is always removed. */ }}resetSession();login();}
function heading(kicker,title,subtitle,badge=''){return `<div class="page-heading"><div><div class="eyebrow">${esc(kicker)}</div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>${badge?`<span class="pill">${esc(badge)}</span>`:''}</div>`;}
function footer(){return `<footer class="bottomline"><span>ServerH Control <span class="slash">/</span> Staff operations</span><span class="mono">GROUP 988023438 · UNIVERSE 7933292768</span></footer>`;}
function navigate(page){
 if(!sessionToken||!actor||!names[page])return;
 clearTimeout(chatTimer);current=page;selected=null;viewEpoch++;
 $('.shell').classList.remove('menu-open');syncMenu();
 for(const b of document.querySelectorAll('[data-nav]')){b.classList.toggle('active',b.dataset.nav===page);b.setAttribute('aria-current',b.dataset.nav===page?'page':'false');}
 $('#crumb').textContent=names[page];
 const content=$('#content');content.innerHTML=`<section class="page-enter">${({overview:overviewHTML,members:membersHTML,moderation:moderationHTML,audit:auditHTML,chat:chatHTML,system:systemHTML}[page])()}</section>${footer()}`;
 content.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.go)));
 if(page==='members'||page==='moderation')bindOperations(page);
 if(page==='audit'){ $('#audit-search').addEventListener('input',renderAudit);$('#audit-export').addEventListener('click',exportAudit);$('#audit-refresh').addEventListener('click',refreshAudit); }
 if(page==='chat')bindChat(viewEpoch);
 if(page==='system'){$('#health-refresh').addEventListener('click',refreshHealth);bindFrames();}
 window.scrollTo({top:0,behavior:'instant'});
}
function statusHTML(status){return `<span class="status ${['succeeded','failed','unknown','pending'].includes(status)?status:'unknown'}"><span class="dot"></span>${esc(status)}</span>`;}
function tableHTML(entries,full=false){if(!entries.length)return `<div class="empty">${icon('log')}No actions recorded${full?'.':' yet.'}<p class="hint">Confirmed operations will appear here.</p></div>`;
 return `<div class="table-wrap"><table><thead><tr><th>Action / Target</th><th>Operator</th>${full?'<th>Reason</th>':''}<th>Result</th><th>Time</th></tr></thead><tbody>${entries.map(a=>`<tr><td>${esc(labels[a.action]||a.action)}<span class="sub mono">USER ${esc(a.target_id)}${full?` / #${esc(a.id)}`:''}</span></td><td>${esc(a.actor)}<span class="sub">Staff operator</span></td>${full?`<td class="audit-reason">${esc(a.reason)}${a.details?.privateReason?`<details><summary>Internal note</summary><pre>${esc(a.details.privateReason)}</pre></details>`:''}</td>`:''}<td>${statusHTML(a.status)}</td><td title="${esc(new Date(a.at).toLocaleString())}">${esc(new Date(a.at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}))}<span class="sub">${esc(new Date(a.at).toLocaleDateString([],{month:'short',day:'numeric'}))}</span></td></tr>`).join('')}</tbody></table></div>`;}
function overviewHTML(){
 const succeeded=audit.filter(a=>a.status==='succeeded').length,attention=audit.filter(a=>a.status!=='succeeded').length;
 return heading('Operations / Overview','The room is yours.',`Welcome back, ${actor.name}. Here’s your operations desk.`,'LEAD OPERATOR +')+`<div class="stats stagger"><div class="panel stat">${icon('log')}<div class="label">Actions logged</div><div class="value">${audit.length.toString().padStart(2,'0')}</div><p class="hint">Latest 100 audit records</p></div><div class="panel stat">${icon('shield')}<div class="label">Completed</div><div class="value">${succeeded.toString().padStart(2,'0')}</div><p class="hint">Confirmed by Roblox</p></div><div class="panel stat">${icon('clock')}<div class="label">Needs review</div><div class="value">${attention.toString().padStart(2,'0')}</div><p class="hint">Failed, pending, or unconfirmed</p></div></div><div class="dashboard-grid"><section class="panel"><div class="panel-head row between"><h2>Start an operation</h2><span class="eyebrow">Quick access</span></div><div class="quick-list"><button class="quick-item" data-go="members"><span class="quick-icon">${icon('rank')}</span><span><b>Look up a user</b><small>Look up an account and update group roles.</small></span>${icon('arrow')}</button><button class="quick-item" data-go="moderation"><span class="quick-icon">${icon('shield')}</span><span><b>Make a moderation call</b><small>Ban any eligible Roblox account, including non-members.</small></span>${icon('arrow')}</button><button class="quick-item" data-go="audit"><span class="quick-icon">${icon('log')}</span><span><b>Follow the paper trail</b><small>Review staff actions and their outcomes.</small></span>${icon('arrow')}</button></div></section><section class="panel access-panel"><div class="access-header">${icon('lock')}<h2>A little structure.<br>A lot of accountability.</h2><p>Your verified identity and current group roles determine what you can do here.</p></div><div class="access-rule"><span>Access level</span><b>${esc(actor.role)}</b></div><div class="access-rule"><span>Identity</span><b>Roblox bio verified</b></div><div class="access-rule"><span>Action review</span><b>Always required</b></div></section></div><section class="panel activity"><div class="panel-head row between"><h2>Recent activity</h2><button class="text-button row" data-go="audit">View audit log ${icon('arrow')}</button></div>${tableHTML(audit.slice(0,5))}</section>`;
}
function lookupHTML({includeResult=true}={}){return `<form id="lookup-form"><label for="target-id">Roblox username or user ID</label><div class="lookup"><input id="target-id" name="query" placeholder="Username or numeric user ID" pattern="[A-Za-z0-9_]{1,20}" maxlength="20" spellcheck="false" required autocomplete="off"><button type="submit" class="button">${icon('search')} Look up</button></div><p class="hint">Find any Roblox account, including people outside ServerH. Use a username, not a display name.</p></form>${includeResult?'<div id="target-result" aria-live="polite"></div>':''}`;}
function directoryHTML(){return `<section class="panel member-directory" aria-label="Group member directory"><div class="panel-head row between"><div><h2>Group members</h2><p class="hint" id="member-count">ServerH community</p></div><button class="button small" id="members-refresh" type="button" aria-label="Refresh member list">${icon('refresh')} Refresh</button></div><div class="panel-body"><form id="member-search-form"><label for="member-search">Search group members</label><div class="directory-search">${icon('search')}<input type="search" id="member-search" maxlength="50" placeholder="Name, username, or role" autocomplete="off"></div></form><p class="hint directory-help">Select a person to fill in their account automatically.</p><div id="member-list" class="member-list" aria-label="Group members" aria-busy="true"><div class="directory-message"><span class="spinner"></span> Loading group members</div></div><div class="directory-pagination"><button id="members-prev" class="button small" type="button" disabled>Previous</button><span id="members-page" class="hint" aria-live="polite">Loading</span><button id="members-next" class="button small" type="button" disabled>Next</button></div><details class="directory-lookup"><summary>Find someone outside the group</summary>${lookupHTML({includeResult:false})}</details><div id="target-result" aria-live="polite"></div></div></section>`;}
function membersHTML(){return heading('Directory / People','People, in the right places.','Choose someone from the group, then update their roles.','GROUP OPERATIONS')+`<div class="form-grid"><div class="stack">${directoryHTML()}<section class="panel"><div class="panel-head"><h2>Update group roles</h2></div><form id="operation-form" class="panel-body"><div id="operation-error"></div><div class="form-pair"><div class="field"><label for="action">Operation</label><select id="action"><option value="assign-role">Assign role</option><option value="remove-role">Remove role</option></select></div><div class="field"><label for="role-id">Role</label><select id="role-id"><option value="">Select a role</option>${me.roles.map(r=>`<option value="${esc(r.id)}">${esc(r.name)}</option>`).join('')}</select></div></div><p class="hint" id="role-help">Assigning adds the selected role. Other roles stay assigned. To move a member, remove the old role separately.</p><div class="divider"></div>${reasonHTML('Reason for this change','For example: completed training and passed the staff review.')}<div class="form-actions"><span>Only roles below your level can be managed.</span><button id="review-action" type="submit" class="button primary" disabled>Review change ${icon('arrow')}</button></div></form></section></div><aside><section class="panel"><div class="panel-head"><h2>Before you make a change</h2></div><div class="panel-body"><div class="facts"><div class="fact"><span>Community</span><b>ServerH</b></div><div class="fact"><span>Your role</span><b>${esc(actor.role)}</b></div><div class="fact"><span>Protected roles</span><b>Lead Operator and higher</b></div><div class="fact"><span>Access</span><b>Rechecked before changes</b></div></div><div class="case-note"><h3>A role carries responsibility.</h3><p>Confirm the user ID and select the right role. Add a reason that another operator can understand later.</p></div></div></section></aside></div>`;}
function reasonHTML(label,placeholder){return `<div class="field"><div class="row between"><label for="reason">${esc(label)} <span class="slash">*</span></label><span class="hint" id="reason-count">0 / 400</span></div><textarea id="reason" name="reason" minlength="10" maxlength="400" required placeholder="${esc(placeholder)}"></textarea><p class="hint">Required. At least 10 characters. Be specific.</p></div>`;}
function moderationHTML(){return heading('Safety / Moderation','Make the call. Leave the context.','Manage access to the ServerH group and experience.','EVERY ACTION IS LOGGED')+`<div class="form-grid"><div class="stack">${directoryHTML()}<section class="panel"><div class="panel-head row between"><h2>Moderation action</h2><span class="pill red">Staff only</span></div><form id="operation-form" class="panel-body"><div id="operation-error"></div><div class="field"><label for="action">Action</label><select id="action">${['experience-ban','experience-unban','kick','group-ban','group-unban'].map(a=>`<option value="${a}">${labels[a]}</option>`).join('')}</select></div><div id="ban-options"><div class="form-pair"><div class="field"><label for="duration">Ban duration</label><select id="duration"><option value="3600">1 hour</option><option value="86400" selected>24 hours</option><option value="604800">7 days</option><option value="2592000">30 days</option><option value="custom">Custom duration</option><option value="permanent">Permanent</option></select></div><div class="field"><label for="ban-scope">Scope</label><input id="ban-scope" value="ServerH · Entire experience" readonly></div></div><div id="custom-duration" class="form-pair" hidden><div class="field"><label for="custom-amount">Length</label><input type="number" id="custom-amount" min="1" max="525600" step="1" value="60"></div><div class="field"><label for="custom-unit">Unit</label><select id="custom-unit"><option value="60">Minutes</option><option value="3600">Hours</option><option value="86400">Days</option></select></div></div></div>${reasonHTML('Reason','Explain what happened and which rule was broken.')}<div id="internal-options"><div class="field"><label for="private-reason">Internal note <span class="slash">*</span></label><textarea id="private-reason" minlength="10" maxlength="800" required placeholder="Add evidence, a case reference, and any relevant warnings."></textarea><p class="hint">Staff only. 10–800 characters.</p></div><label class="check-label"><input type="checkbox" id="include-alts"><span>Include suspected alternate accounts<small>Let Roblox extend the ban to accounts it associates with this user.</small></span></label></div><div class="case-note" id="action-note"><h3>Visible to the player</h3><p>Your reason is shown when the player tries to join. Internal notes remain private. Temporary bans expire through Roblox automatically.</p></div><div class="form-actions"><span id="action-footer">A reason is required for every moderation action.</span><button type="submit" id="review-action" class="button primary" disabled>Review action ${icon('arrow')}</button></div></form></section></div><aside><section class="panel"><div class="panel-head"><h2>Moderation, with context</h2></div><div class="panel-body"><div class="facts"><div class="fact"><span>Experience</span><b>ServerH</b></div><div class="fact"><span>Universe</span><b class="mono">7933292768</b></div><div class="fact"><span>Ban system</span><b>Roblox user restrictions</b></div><div class="fact"><span>Temporary bans</span><b>Automatic expiry</b></div></div><div class="case-note"><h3>Check twice. Act once.</h3><p>Review the account, duration, and reason before confirming. If a result is unconfirmed, check Roblox’s ban history before submitting again.</p></div><div class="divider"></div><a class="text-button row" href="https://create.roblox.com/dashboard/creations/experiences/7933292768/safety/bans" target="_blank" rel="noopener noreferrer">Open Creator Hub bans ${icon('external')}</a></div></section></aside></div>`;}
function profileHTML(v){
 const note=v.policyConfirmed===false?'This account can be viewed, but its roles need owner review before any action.':!v.manageable?'This account is protected. You cannot act on it.':!v.isMember?'Not in the group. Use Moderation to ban or unban this account. Group role changes and kicks require membership.':!v.roles.length?'Group member with no assigned role. You can assign an eligible role or use Moderation.':'';
 return `<div class="profile-result">${avatar(v)}<span><h3>${esc(v.displayName||v.name)}</h3><span class="hint">@${esc(v.name)} <span class="mono">/ ${esc(v.id)}</span></span></span>${badges(v)}</div>${note?`<p class="hint">${esc(note)}</p>`:''}`;
}
function bindOperations(page){
 const epoch=viewEpoch;
 const eligible=()=>Boolean(selected?.allowedActions?.includes($('#action').value));
 const syncEligibility=()=>{$('#review-action').disabled=!eligible();};
 $('#action').addEventListener('change',syncEligibility);
 let selectionVersion=0;
 const clearSelection=()=>{selectionVersion++;selected=null;syncEligibility();$('#target-result').innerHTML='';document.querySelectorAll('[data-member-id]').forEach(button=>button.setAttribute('aria-pressed','false'));};
 const selectAccount=async(query,button)=>{
  clearSelection();const version=selectionVersion;busy(button,true,'Selecting');
  try{const user=(await api('/users/lookup',{method:'POST',data:{query}})).user;
   if(viewEpoch!==epoch||version!==selectionVersion)return;
   selected=user;$('#target-result').innerHTML=profileHTML(user);syncEligibility();
   document.querySelectorAll('[data-member-id]').forEach(row=>row.setAttribute('aria-pressed',String(row.dataset.memberId===user.id)));
   $('#target-result').scrollIntoView({behavior:'smooth',block:'nearest'});
  }catch(err){if(viewEpoch===epoch&&version===selectionVersion)errorBox($('#target-result'),err.message);}
  finally{if(button?.isConnected)busy(button,false);}
 };
 $('#lookup-form').addEventListener('submit',e=>{e.preventDefault();selectAccount($('#target-id').value.trim(),$('button',e.currentTarget));});
 $('#target-id').addEventListener('input',clearSelection);
 bindDirectory(epoch,selectAccount);
 $('#reason').addEventListener('input',()=>{$('#reason-count').textContent=`${$('#reason').value.length} / 400`;});
 if(page==='moderation'){
  $('#action').addEventListener('change',()=>{const ban=$('#action').value==='experience-ban';$('#ban-options').hidden=!ban;$('#internal-options').hidden=!ban;$('#private-reason').required=ban;$('#custom-amount').required=ban&&$('#duration').value==='custom';$('#action-note').innerHTML=ban?'<h3>Visible to the player</h3><p>Your reason is shown when the player tries to join. Internal notes remain private. Temporary bans expire through Roblox automatically.</p>':$('#action').value==='kick'?'<h3>Group removal</h3><p>This removes the account from the group. They can rejoin if your group allows it. It does not disconnect them from a live game.</p>':$('#action').value==='experience-unban'?'<h3>Experience unban</h3><p>This removes the universe-level restriction. Separate place-level restrictions or Roblox device blocks may need to be reviewed in Roblox.</p>':'<h3>Group membership</h3><p>Group bans and group unbans affect membership in the community. Experience restrictions are managed separately.</p>';});
  $('#duration').addEventListener('change',()=>{const custom=$('#duration').value==='custom';$('#custom-duration').hidden=!custom;$('#custom-amount').required=custom;});
 }
 $('#operation-form').addEventListener('submit',async e=>{
  e.preventDefault();if(!eligible())return toast('Look up an account eligible for this action first.');
  const action={action:$('#action').value,targetId:selected.id,reason:$('#reason').value.trim()};
  if(action.reason.length<10)return errorBox($('#operation-error'),'Give a clear reason with at least 10 characters.');
  if(page==='members'){action.roleId=$('#role-id').value;if(!action.roleId)return errorBox($('#operation-error'),'Choose a role.');}
  if(action.action==='experience-ban'){
   action.duration=$('#duration').value==='permanent'?'permanent':$('#duration').value==='custom'?Number($('#custom-amount').value)*Number($('#custom-unit').value):Number($('#duration').value);
   if(action.duration!=='permanent'&&(!Number.isSafeInteger(action.duration)||action.duration<60||action.duration>31536000))return errorBox($('#operation-error'),'Choose a duration between 1 minute and 365 days.');
   action.privateReason=$('#private-reason').value.trim();action.includeAlts=$('#include-alts').checked;
   if(action.privateReason.length<10)return errorBox($('#operation-error'),'Add an internal note with at least 10 characters.');
  }
  const btn=$('#review-action');busy(btn,true,'Checking permissions');$('.inline-error',$('#operation-error'))?.remove();
  try{const plan=await api('/actions/prepare',{method:'POST',data:action});if(viewEpoch===epoch)showReview(plan);}
  catch(err){if(viewEpoch===epoch)errorBox($('#operation-error'),err.message);}finally{if(btn.isConnected)busy(btn,false);}
 });
}
function bindDirectory(epoch,selectAccount){
 let page=1,totalPages=1,query='',requestVersion=0,searchTimer;
 const list=$('#member-list'),prev=$('#members-prev'),next=$('#members-next'),refresh=$('#members-refresh');
 async function load(targetPage=1,force=false){
  if(viewEpoch!==epoch)return;
  const version=++requestVersion;
  list.setAttribute('aria-busy','true');prev.disabled=true;next.disabled=true;refresh.disabled=true;
  $('#members-page').textContent='Loading';
  const params=new URLSearchParams({page:String(targetPage),search:query,...(force?{refresh:'1'}:{})});
  try{
   const result=await api('/members?'+params);
   if(viewEpoch!==epoch||version!==requestVersion)return;
   page=result.page;totalPages=result.totalPages;
   $('#member-count').textContent=query?`${result.total} matching / ${result.totalMembers} members`:`${result.totalMembers} members`;
   list.innerHTML=result.members.length?result.members.map(member=>`<button type="button" class="directory-member" data-member-id="${esc(member.id)}" aria-pressed="${String(selected?.id===member.id)}" aria-label="Select ${esc(member.name)}">${avatar(member)}<span class="directory-person"><b>${esc(member.displayName||member.name)}</b><span>@${esc(member.name)}</span></span>${badges(member)}<span class="directory-select">Select ${icon('arrow')}</span></button>`).join(''):`<div class="directory-message">${query?'No group members match that search.':'No group members found.'}</div>`;
   $('#members-page').textContent=`Page ${page} of ${totalPages}`;
   prev.disabled=page<=1;next.disabled=page>=totalPages;
  }catch(err){
   if(viewEpoch!==epoch||version!==requestVersion)return;
   list.innerHTML=`<div class="directory-message"><p>${esc(err.message)}</p><button type="button" class="button small" data-directory-retry>Try again</button></div>`;
   $('#members-page').textContent='Unavailable';$('#member-count').textContent='Could not load members';
  }finally{if(viewEpoch===epoch&&version===requestVersion){list.setAttribute('aria-busy','false');refresh.disabled=false;}}
 }
 list.addEventListener('click',event=>{const row=event.target.closest('[data-member-id]');if(row)selectAccount(row.dataset.memberId,row);else if(event.target.closest('[data-directory-retry]'))load(page,true);});
 prev.addEventListener('click',()=>load(page-1));next.addEventListener('click',()=>load(page+1));refresh.addEventListener('click',()=>load(page,true));
 const search=()=>{clearTimeout(searchTimer);query=$('#member-search').value.trim();load(1);};
 $('#member-search-form').addEventListener('submit',event=>{event.preventDefault();search();});
 $('#member-search').addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{if(viewEpoch===epoch)search();},300);});
 load();
}
function durationLabel(v){return v==='permanent'?'Permanent':v%86400===0?`${v/86400} day${v===86400?'':'s'}`:v%3600===0?`${v/3600} hour${v===3600?'':'s'}`:`${v/60} minutes`;}
function showReview(plan){
 review=plan;const a=plan.action,r=me.roles.find(r=>r.id===a.roleId);
 $('#review-content').innerHTML=`<div class="dialog-top"><div class="eyebrow">Final review / Live operation</div><h2 id="review-title">${esc(labels[a.action])}</h2></div><div class="dialog-body"><div class="facts"><div class="fact"><span>Account</span><b>@${esc(plan.target.name)}</b></div><div class="fact"><span>User ID</span><b class="mono">${esc(a.targetId)}</b></div>${r?`<div class="fact"><span>Role</span><b>${esc(r.name)}</b></div>`:''}${a.duration?`<div class="fact"><span>Duration</span><b>${esc(durationLabel(a.duration))}</b></div><div class="fact"><span>Suspected alts</span><b>${a.includeAlts?'Included':'Excluded'}</b></div>`:''}</div><p class="hint">${a.action==='experience-ban'?'Player-facing reason':'Reason'}</p><div class="dialog-reason">${esc(a.reason)}</div>${a.privateReason?`<p class="hint">Internal note</p><div class="dialog-reason">${esc(a.privateReason)}</div>`:''}<div class="notice">Confirm the account and action. This review expires in 2 minutes.</div><div id="confirm-error"></div></div><div class="dialog-actions"><button id="cancel-review" class="button ghost">Go back</button><button id="confirm-action" class="button primary">Confirm ${icon('arrow')}</button></div>`;
 $('#cancel-review').addEventListener('click',()=>dialog.close());
 $('#confirm-action').addEventListener('click',confirmAction);
 dialog.showModal();
}
async function confirmAction(){
 if(!sessionToken||!review?.intentToken)return;
 const plan=review,btn=$('#confirm-action');busy(btn,true,'Submitting');$('#cancel-review').disabled=true;
 try{const result=await api('/actions/confirm',{method:'POST',data:{intentToken:plan.intentToken}});dialog.close();review=null;toast(`Action completed. Audit entry #${result.auditId}.`);audit=(await api('/audit')).entries;navigate('audit');}
 catch(err){if(dialog.open){errorBox($('#confirm-error'),err.message+' Check the audit log before making another request.');btn.disabled=true;btn.innerHTML='Submitted / check audit';$('#cancel-review').disabled=false;}}
}
function auditHTML(){return heading('Accountability / Audit log','Every action has a trail.','Review the latest 100 panel operations, their reasons, and their results.','STAFF RECORDS')+`<section class="panel"><div class="toolbar"><input id="audit-search" type="search" placeholder="Search user ID, operator, or reason" aria-label="Search audit log"><span class="hint">${audit.length} records</span><button id="audit-refresh" class="icon-button" title="Refresh audit log" aria-label="Refresh audit log">${icon('refresh')}</button><button id="audit-export" class="button small">${icon('download')} Export CSV</button></div><div id="audit-table">${tableHTML(audit,true)}</div></section><div class="case-note"><h3>An unconfirmed result needs a second look.</h3><p>“Unknown” means Roblox did not confirm the outcome, or the backend restarted mid-request. Check the member or Creator Hub before submitting another action.</p></div>`;}
function renderAudit(){const q=$('#audit-search').value.toLowerCase();$('#audit-table').innerHTML=tableHTML(audit.filter(a=>[a.target_id,a.actor,a.action,labels[a.action],a.reason,String(a.id)].some(v=>String(v).toLowerCase().includes(q))),true);}
async function refreshAudit(){const btn=$('#audit-refresh');busy(btn,true);try{audit=(await api('/audit')).entries;if(current==='audit')navigate('audit');toast('Audit log refreshed.');}catch(e){toast(e.message);}finally{if(btn.isConnected)busy(btn,false);}}
function exportAudit(){
 const fields=['id','at','actor_id','actor','target_id','action','reason','status'];
 const csv=fields.join(',')+'\r\n'+audit.map(a=>fields.map(f=>{let s=String(a[f]??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}).join(',')).join('\r\n');
 const url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='serverh-audit.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function systemHTML(){return heading('Workspace / Connection','The machinery behind the desk.','Your account, connected services, and session details.','CONNECTION DETAILS')+profileSettingsHTML()+`<div class="form-grid"><section class="panel"><div class="panel-head row between"><h2>Workspace connection</h2><button id="health-refresh" class="button small">${icon('refresh')} Check connection</button></div><div class="panel-body"><div class="facts"><div class="fact"><span>Signed in as</span><b>${esc(actor.name)}</b></div><div class="fact"><span>Current role</span><b>${esc(actor.role)}</b></div><div class="fact"><span>Authentication</span><b>Roblox bio verification</b></div><div class="fact"><span>Role updates / experience bans</span><b>${me.capabilities.experienceBans?'Open Cloud configured':'Not configured'}</b></div><div class="fact"><span>Group removals / group bans</span><b>${me.capabilities.groupActions?'Bot cookie configured':'Cookie not configured'}</b></div><div class="fact"><span>Backend</span><b id="health-label">Connected</b></div></div><div class="case-note"><h3>Account credentials stay on the server.</h3><p>Staff connect through their Roblox bio. No passwords, cookies, or API keys are requested in this panel.</p></div></div></section><aside class="panel"><div class="panel-head"><h2>Workspace links</h2></div><div class="quick-list"><a class="quick-item" href="https://www.roblox.com/communities/988023438/ServerH#!/about" target="_blank" rel="noopener noreferrer"><span><b>ServerH community</b><small>988023438</small></span>${icon('external')}</a><a class="quick-item" href="https://www.roblox.com/games/91495780481344/Server-Owner" target="_blank" rel="noopener noreferrer"><span><b>ServerH experience</b><small>Server Owner</small></span>${icon('external')}</a><a class="quick-item" href="https://create.roblox.com/dashboard/creations/experiences/7933292768/safety/bans" target="_blank" rel="noopener noreferrer"><span><b>Creator Hub moderation</b><small>Review experience bans</small></span>${icon('external')}</a></div></aside></div>`;}

function profileSettingsHTML(){return `<section class="panel profile-settings"><div class="profile-identity">${avatar(actor,'avatar-large')}<div><div class="eyebrow">Your Roblox profile</div><h2>${esc(actor.name)}</h2>${badges(actor)}</div><a class="button small" href="https://www.roblox.com/users/${esc(actor.id)}/profile#!/about" target="_blank" rel="noopener noreferrer">View profile ${icon('external')}</a></div><div class="frame-settings"><div><h3>Profile frame</h3><p class="hint">Choose your look in ServerH. Rank badges always follow your group roles.</p></div><div class="frame-choices" role="group" aria-label="Profile frame">${Object.entries(frameNames).map(([key,label])=>`<button type="button" class="frame-choice ${actor.frame===key?'chosen':''}" data-frame="${key}" aria-pressed="${actor.frame===key}">${avatar({...actor,frame:key})}<span>${label}</span></button>`).join('')}</div><p class="hint">These frames appear in this panel. Your Roblox profile stays managed on Roblox.</p><div id="frame-error"></div></div></section>`;}
function bindFrames(){for(const button of document.querySelectorAll('[data-frame]'))button.addEventListener('click',async()=>{const epoch=viewEpoch;document.querySelectorAll('[data-frame]').forEach(b=>b.disabled=true);try{const result=await api('/profile/frame',{method:'POST',data:{frame:button.dataset.frame}});if(viewEpoch!==epoch)return;actor=result.user;me.user=actor;shell();navigate('system');toast('Profile frame saved.');}catch(e){if(viewEpoch===epoch){errorBox($('#frame-error'),e.message);document.querySelectorAll('[data-frame]').forEach(b=>b.disabled=false);}}});}
function chatHTML(){return heading('Staff / Conversations','Keep your team in the loop.','Private conversations with staff who have connected to ServerH.','VERIFIED STAFF')+`<section class="panel chat-layout"><aside class="chat-people"><div class="panel-head row between"><h2>Team</h2><button type="button" id="chat-refresh" class="icon-button" aria-label="Refresh staff list">${icon('refresh')}</button></div><div class="chat-contact-search"><label class="sr-only" for="chat-search">Search staff</label><input id="chat-search" type="search" placeholder="Find a staff member" maxlength="50"></div><div id="chat-contacts" class="chat-contacts" aria-live="polite"><p class="directory-message">Loading staff…</p></div><p class="hint chat-footnote">Staff appear after their first verified sign-in.</p></aside><div class="chat-conversation" id="chat-conversation"><div class="chat-welcome">${icon('chat')}<h2>A direct line to your team.</h2><p class="muted">Select a staff member to start a conversation.</p><p class="hint">Messages are stored on the private ServerH backend.</p></div></div></section>`;}
function bindChat(epoch){
 let contacts=[],peer=null,conversationVersion=0,messages=[],hasMore=false,loading=false,pending=new Map();
 const active=()=>viewEpoch===epoch&&Boolean(actor), contactsRoot=$('#chat-contacts');
 function renderContacts(){const q=$('#chat-search').value.trim().toLowerCase();const found=contacts.filter(p=>[p.name,p.role,...(p.badges||[]).map(b=>b.label)].some(v=>v.toLowerCase().includes(q)));contactsRoot.innerHTML=found.length?found.map(p=>`<button type="button" class="chat-contact ${peer?.id===p.id?'chosen':''}" data-chat-peer="${esc(p.id)}" aria-pressed="${peer?.id===p.id}">${avatar(p)}<span><b>${esc(p.name)}</b>${badges(p)}</span>${icon('arrow')}</button>`).join(''):`<div class="directory-message">${contacts.length?'No staff match your search.':'No other staff have connected yet. They will appear here after verifying their account.'}</div>`;}
 async function loadContacts(){const button=$('#chat-refresh');button.disabled=true;try{const r=await api('/chat/contacts');if(!active())return;contacts=r.contacts;renderContacts();}catch(e){if(active())contactsRoot.innerHTML=`<p class="directory-message">${esc(e.message)}</p>`;}finally{if(button.isConnected)button.disabled=false;}}
 function renderMessages(forceBottom=false){const root=$('#chat-messages'),nearBottom=root.scrollHeight-root.scrollTop-root.clientHeight<90,oldHeight=root.scrollHeight,oldTop=root.scrollTop;root.innerHTML=messages.length?messages.map(m=>`<article class="chat-message ${m.sender===actor.id?'outgoing':'incoming'}">${avatar(m.sender===actor.id?actor:peer)}<div><div class="message-meta"><b>${m.sender===actor.id?'You':esc(peer.name)}</b><time datetime="${esc(new Date(m.at).toISOString())}">${esc(new Date(m.at).toLocaleString([],{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}))}</time></div><p>${esc(m.content)}</p></div></article>`).join(''):'<div class="chat-empty">No messages yet. Start the conversation below.</div>';if(forceBottom||nearBottom)root.scrollTop=root.scrollHeight;else root.scrollTop=oldTop+(root.scrollHeight-oldHeight);$('#chat-older').hidden=!hasMore;}
 async function loadMessages(older=false){if(!active()||!peer||loading)return;loading=true;const version=conversationVersion;try{const q=new URLSearchParams({peer:peer.id,...(older&&messages.length?{before:String(messages[0].id)}:{})}),r=await api('/chat/messages?'+q);if(!active()||version!==conversationVersion)return;peer=r.peer;const merged=new Map(messages.map(m=>[m.id,m]));for(const message of r.messages)merged.set(message.id,message);const changed=merged.size!==messages.length;messages=[...merged.values()].sort((a,b)=>a.id-b.id);if(older||messages.length<=50)hasMore=r.hasMore;if(changed||!messages.length)renderMessages();$('#chat-status').textContent='Staff access confirmed';}catch(e){if(active()&&version===conversationVersion){$('#chat-status').textContent='Updates paused';errorBox($('#chat-errors'),e.message);}}finally{if(version===conversationVersion)loading=false;}}
 async function selectPeer(id){clearTimeout(chatTimer);const selectedVersion=++conversationVersion;loading=false;peer=contacts.find(c=>c.id===id);messages=[];hasMore=false;renderContacts();$('#chat-conversation').innerHTML=`<header class="chat-header">${avatar(peer)}<div><h2>${esc(peer.name)}</h2>${badges(peer)}</div><span class="hint" id="chat-status">Connecting</span></header><div class="chat-history"><button type="button" id="chat-older" class="text-button" hidden>Load earlier messages</button><div id="chat-messages" class="chat-messages" aria-label="Conversation messages" aria-live="polite"></div></div><div id="chat-errors"></div><form id="chat-compose" class="chat-compose"><label class="sr-only" for="chat-text">Message ${esc(peer.name)}</label><textarea id="chat-text" placeholder="Message @${esc(peer.name)}" required maxlength="2000" rows="2"></textarea><div class="row between"><span class="hint" id="chat-count">0 / 2,000 · Ctrl + Enter to send</span><button type="submit" class="button primary" id="chat-send">Send ${icon('arrow')}</button></div></form>`;
 $('#chat-older').addEventListener('click',()=>loadMessages(true));$('#chat-text').addEventListener('input',()=>{$('#chat-count').textContent=`${$('#chat-text').value.length} / 2,000 · Ctrl + Enter to send`;});$('#chat-text').addEventListener('keydown',e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();$('#chat-compose').requestSubmit();}});
 $('#chat-compose').addEventListener('submit',async e=>{e.preventDefault();const content=$('#chat-text').value.trim();if(!content)return;const version=conversationVersion,button=$('#chat-send'),text=$('#chat-text'),key=peer.id+'\n'+content;let nonce=pending.get(key);if(!nonce){nonce=crypto.randomUUID();pending.set(key,nonce);}busy(button,true,'Sending');text.disabled=true;$('#chat-errors').innerHTML='';try{const r=await api('/chat/messages',{method:'POST',data:{peerId:peer.id,content,nonce}});pending.delete(key);if(!active()||version!==conversationVersion)return;if(!messages.some(m=>m.id===r.message.id))messages.push(r.message);text.value='';$('#chat-count').textContent='0 / 2,000 · Ctrl + Enter to send';renderMessages(true);}catch(err){if(active()&&version===conversationVersion)errorBox($('#chat-errors'),err.message+' Your draft is kept. Retrying this draft will not duplicate it.');}finally{if(button.isConnected){busy(button,false);text.disabled=false;}}});
 await loadMessages();if(!active()||selectedVersion!==conversationVersion)return;async function poll(){if(!active()||!peer||selectedVersion!==conversationVersion)return;if(!document.hidden)await loadMessages();if(active()&&selectedVersion===conversationVersion)chatTimer=setTimeout(poll,10000);}if(active()&&selectedVersion===conversationVersion)chatTimer=setTimeout(poll,10000);
 }
 contactsRoot.addEventListener('click',e=>{const row=e.target.closest('[data-chat-peer]');if(row)selectPeer(row.dataset.chatPeer);});$('#chat-search').addEventListener('input',renderContacts);$('#chat-refresh').addEventListener('click',loadContacts);loadContacts();
}

async function refreshHealth(){const btn=$('#health-refresh');busy(btn,true,'Checking');try{const health=await api('/health');await api('/me');if(current==='system')$('#health-label').textContent=health.configured?'Backend running':'Setup incomplete';toast('Connection checked.');}catch(e){if(current==='system')$('#health-label').textContent='Connection failed';toast(e.message);}finally{if(btn.isConnected)busy(btn,false);}}
setInterval(()=>{if(!actor)return;const left=Math.max(0,Math.ceil((actor.expires-Date.now())/1000));if($('#session-clock'))$('#session-clock').textContent=`SESSION / ${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;if(!left){resetSession();login();toast('Session ended. Connect your Roblox account again.');}},1000);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('.shell')?.classList.contains('menu-open'))closeMenu();});
async function restoreSession(){
 const remembered=sessions.read();
 if(!remembered){login();return;}
 sessionToken=remembered.token;
 app.innerHTML='<main class="login"><section class="login-form"><h1>Restoring your session.</h1><p class="muted">Checking your current Roblox access.</p></section></main>';
 try{await loadPanel();}catch(err){login();toast(err.message);}
}
restoreSession();
})();
